CREATE FUNCTION public.public_institution_directory() RETURNS TABLE(id uuid,name text,kind text,logo_path text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT id,name,kind,logo_path FROM public.institutions WHERE NOT is_test AND logo_path IS NOT NULL ORDER BY name LIMIT 300; $$; REVOKE ALL ON FUNCTION public.public_institution_directory() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.public_institution_directory() TO anon,authenticated;